def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    """
    Manually parses CSV text according to custom rules.
    Does NOT use the csv module.

    Rules:
    - Records are separated by \n or \r\n. Trailing line break does not create a new record.
    - Empty text returns [].
    - An empty line in the middle is a single empty-field record: [""].
    - Fields starting with a double quote can contain a line break and a single ". Quotes are NOT included.
    - Unquoted fields are taken as-is (spaces preserved); " in the middle of an unquoted field is treated as a regular character.
    - ValueError raised on malformed input:
        * An unclosed quote (no closing quote).
        * A closing quote immediately followed by a character other than the delimiter or line break.
    """
    if not text:
        return []

    lines = text.split('\n')

    # Remove trailing empty line if the text ended with a line break
    if lines and lines[-1] == '':
        lines = lines[:-1]

    if not lines:
        return []

    records = []

    for line in lines:
        if line == '':
            # Empty line is a single empty-field record
            records.append([''])
        else:
            row = []
            pos = 0
            while pos < len(line):
                field = parse_field(line, delimiter, pos)
                row.append(field)
                # The field string doesn't include delimiter or newline
                pos += len(field)
                if pos >= len(line):
                    break
                next_char = line[pos]
                if next_char == delimiter:
                    pos += 1
                elif next_char == '\r':
                    raise ValueError("Malformed CSV: unexpected \\r")
                elif next_char == '\n':
                    records.append(row)
                    break
                else:
                    raise ValueError(f"Malformed CSV: invalid character '{next_char}' after field")

            else:
                # We exited loop without hitting newline -> end of line
                records.append(row)

    return records


def parse_field(line: str, delimiter: str, start: int) -> str:
    """
    Parses a single field starting at `start` position.
    Returns the field content.
    The position after the field (including delimiter if present) is indicated by modifying a list [start].
    """
    if start >= len(line):
        return ''

    if line[start] == '"':
        # Quoted field
        pos = start + 1
        while pos < len(line):
            char = line[pos]
            if char == '"':
                # Check if this is the closing quote
                # It must be followed by either delimiter or end of line
                if pos + 1 >= len(line):
                    # End of line with closing quote -> valid
                    return line[start+1:pos]
                elif line[pos+1] == delimiter:
                    # Closing quote followed by delimiter -> valid
                    return line[start+1:pos]
                elif line[pos+1] == '\n':
                    # Closing quote followed by newline -> valid
                    return line[start+1:pos]
                else:
                    # Closing quote followed by something else -> malformed
                    raise ValueError(f"Malformed CSV: closing quote followed by invalid character '{line[pos+1]}'")
            elif pos + 1 < len(line) and line[pos] == '"' and line[pos+1] == '"':
                # Escaped quote "" -> single "
                pos += 2  # Skip both quotes
            else:
                pos += 1
        else:
            # We exited the loop without finding closing quote -> unclosed quote
            raise ValueError("Malformed CSV: unclosed quote")

    else:
        # Unquoted field
        pos = start
        while pos < len(line):
            char = line[pos]
            if char == delimiter:
                # End of field, exclude delimiter
                return line[start:pos]
            elif char == '\r':
                raise ValueError("Malformed CSV: unexpected \\r in unquoted field")
            elif char == '\n':
                # End of field, exclude newline
                return line[start:pos]
            else:
                pos += 1
        else:
            # No delimiter or newline found, field goes to end of line
            return line[start:]

